  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is cumulative frequency?', 'A running total of frequencies.', 1),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you plot a cumulative frequency graph?', 'Plot cumulative frequency against the upper class boundary, and join with a smooth curve.', 2),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you find the median from a cumulative frequency graph?', 'Read across from half the total frequency.', 3),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you find the lower quartile?', 'Read across from a quarter of the total frequency.', 4),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you find the upper quartile?', 'Read across from three quarters of the total frequency.', 5),
