  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'Why is the IQR useful?', 'It measures the spread of the middle 50%, unaffected by outliers.', 7),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is a box plot?', 'A diagram showing the minimum, lower quartile, median, upper quartile and maximum.', 8),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you compare two box plots?', 'Compare the medians (average) and the IQRs or ranges (spread), in context.', 9),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is a histogram?', 'A chart for continuous data where the area of each bar represents frequency.', 10),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is frequency density?', 'Frequency ÷ class width.', 11),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'Why are histograms used for unequal class widths?', 'Frequency density adjusts for the different widths so the areas represent frequencies.', 12),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'Find the frequency density for a class 10 < x ≤ 30 with frequency 40.', '40 ÷ 20 = 2.', 13),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you find frequency from a histogram?', 'Frequency = frequency density × class width.', 14),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you estimate the median from a histogram?', 'Find the value that splits the total area in half.', 15),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What does a steep part of a cumulative frequency curve show?', 'Many values in that range.', 16),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What does a flat part of a cumulative frequency curve show?', 'Few values in that range.', 17),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you estimate the number above a value from a cumulative frequency graph?', 'Read the cumulative frequency at that value and subtract from the total.', 18),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What does a longer whisker in a box plot show?', 'More spread in that part of the data.', 19),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is a symmetrical distribution on a box plot?', 'The median is in the middle of the box, and the whiskers are equal.', 20),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What does positive skew look like on a box plot?', 'The median is closer to the lower quartile, and the upper whisker is longer.', 21),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you find the class width of 20 ≤ x < 35?', '15.', 22),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is the total frequency if a histogram has areas 10, 20 and 30?', '60.', 23),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'Why can''t you draw a histogram with frequency on the y-axis for unequal widths?', 'It would misrepresent the data, as wider classes would look larger.', 24),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you compare distributions from cumulative frequency graphs?', 'Compare medians and IQRs.', 25),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is the median position for n values?', 'The (n + 1)/2 th value.', 26),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'How do you find quartiles for a small data set?', 'Find the medians of the lower and upper halves.', 27),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What does the IQR tell you about consistency?', 'A smaller IQR means more consistent data.', 28),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is an outlier on a box plot?', 'A value more than 1.5 × IQR beyond the quartiles.', 29),
  ('Mathematics', 'OCR', 'gcse', '6.2', 'Cumulative Frequency, Histograms & Box Plots', 'What is the difference between a bar chart and a histogram?', 'Bar charts have gaps and show categories; histograms show continuous data with no gaps and use area for frequency.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Mathematics' AND exam_board = 'OCR' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
